import { finding } from '../../engine/checks/helpers/findings.mjs';
import { workflowFiles } from '../../engine/checks/helpers/github-workflows.mjs';

const rule = {
  id: 'gha/checkout-submodules',
  severity: 'blocking',
  description: 'In a repo with submodules, every actions/checkout must pass submodules: true',
  doc: 'skills/git-github-advanced/SKILL.md',
  why: 'checkout does not fetch submodules by default, so any gate reading submodule content passes vacuously',

  run(ctx) {
    if (!ctx.exists('.gitmodules')) return [];
    const out = [];
    for (const wf of workflowFiles(ctx)) {
      const text = ctx.read(wf);
      if (text === null) continue;
      const lines = text.split('\n');
      for (let i = 0; i < lines.length; i += 1) {
        if (!/uses:\s*actions\/checkout@/.test(lines[i])) continue;
        const stepIndent = lines[i].search(/\S/);
        let covered = false;
        for (let j = i + 1; j < lines.length; j += 1) {
          if (lines[j].trim() && lines[j].search(/\S/) <= stepIndent) break; // next step/key
          if (/submodules:\s*(true|recursive)/.test(lines[j])) { covered = true; break; }
        }
        if (!covered) {
          out.push(finding(rule, {
            file: wf, line: i + 1,
            what: 'actions/checkout without submodules: true in a repo that has .gitmodules',
            fix: 'add `with: submodules: true` (or recursive) to this checkout step',
          }));
        }
      }
    }
    return out;
  },
};

export default rule;
import { finding } from '../../engine/checks/helpers/findings.mjs';
import { workflowFiles } from '../../engine/checks/helpers/github-workflows.mjs';

// A single | between non-| characters is a shell pipe; || is the or-operator.
const PIPE = /(^|[^|])\|([^|]|$)/;

const rule = {
  id: 'gha/run-pipefail',
  severity: 'blocking',
  description: 'A workflow piping in run: steps needs shell: bash — the default shell has no pipefail',
  doc: 'skills/git-github-advanced/SKILL.md',
  why: "GitHub's implicit run shell is bash -e without pipefail, so a failing piped command still shows the step green",

  run(ctx) {
    const out = [];
    for (const wf of workflowFiles(ctx)) {
      const text = ctx.read(wf);
      if (text === null || /shell:\s*bash/.test(text)) continue;
      const lines = text.split('\n');
      for (let i = 0; i < lines.length; i += 1) {
        const inline = /^(\s*)(?:-\s+)?run:\s*(.+)$/.exec(lines[i]);
        if (!inline) continue;
        const runIndent = inline[1].length;
        let commands = [];
        if (/^[|>][+-]?\s*$/.test(inline[2])) {
          for (let j = i + 1; j < lines.length; j += 1) {
            if (lines[j].trim() && !/^\s+/.test(lines[j])) break;
            if (lines[j].trim() && lines[j].search(/\S/) <= runIndent) break;
            commands.push(lines[j]);
            if (!lines[j].trim()) continue;
          }
        } else {
          commands = [inline[2]];
        }
        if (commands.some((c) => PIPE.test(c))) {
          out.push(finding(rule, {
            file: wf, line: i + 1,
            what: 'a piped run: step in a workflow with no bash shell default',
            fix: 'add defaults.run.shell: bash (workflow- or job-level) so the step runs with -o pipefail',
          }));
        }
      }
    }
    return out;
  },
};

export default rule;
import { finding } from '../../engine/checks/helpers/findings.mjs';
import { workflowFiles } from '../../engine/checks/helpers/github-workflows.mjs';

const rule = {
  id: 'gha/secrets-in-job-if',
  severity: 'blocking',
  description: 'A job-level if: cannot read secrets.* — the job fails red instead of skipping',
  doc: 'skills/git-github-advanced/SKILL.md',
  why: 'secrets are not available in a job-level if:, so the condition cannot evaluate and the job fails instead of skipping',

  run(ctx) {
    const out = [];
    for (const wf of workflowFiles(ctx)) {
      const text = ctx.read(wf);
      if (text === null) continue;
      // An if: at or above the current steps: indent is job-level; below it is step-level.
      let stepsIndent = -1;
      text.split('\n').forEach((line, i) => {
        const steps = /^(\s*)steps:\s*$/.exec(line);
        if (steps) { stepsIndent = steps[1].length; return; }
        if (/^\s{0,2}\S/.test(line)) stepsIndent = -1; // new job or top-level key
        const m = /^(\s*)if:\s*(.*)$/.exec(line);
        if (m && /secrets\./.test(m[2]) && (stepsIndent === -1 || m[1].length <= stepsIndent)) {
          out.push(finding(rule, {
            file: wf, line: i + 1,
            what: `job-level if: reads ${/secrets\.\w+/.exec(m[2])?.[0] ?? 'secrets.*'}`,
            fix: 'put the non-sensitive flag in a repository variable and gate with vars.* (if: ${{ vars.X != \'\' }}); keep the secret for the steps inside the job',
          }));
        }
      });
    }
    return out;
  },
};

export default rule;

