+    maxLineLength: { bytes: 100, what: '{count} line(s) over {bytes} bytes, longest {longest}', fix: 'f' },
+  });
+  const root = makeRepo({ changed: {
+    'docs/long.md': `short\n${'é'.repeat(60)}\n${'x'.repeat(150)}\n`,
